    /**
     * Returns the new section id.
     */
    fun `createSection`(`name`: kotlin.String): kotlin.String
    
    /**
     * Mint a chat row (born on chat2). Returns the new chat id.
     */
    fun `createSession`(`newSession`: NewSession): kotlin.String
    
    /**
