     */
    suspend fun `createWorktree`(`deviceId`: kotlin.String, `spaceId`: kotlin.String, `repoPath`: kotlin.String, `base`: kotlin.String): kotlin.String
    
    fun `deleteProject`(`spaceId`: kotlin.String)
    
    fun `deleteSection`(`sectionId`: kotlin.String)
    
    fun `deleteSession`(`chatId`: kotlin.String)
    
    fun `deviceId`(): kotlin.String
    
    fun `devices`(): List<DeviceView>
    
    /**
     * Direct mode: link phase, errors and stream counters (`None` otherwise).
     */
    fun `directStatus`(): DirectStatus?
    
    /**
     * Devices that can run sessions (new-session / new-project pickers).
     */
    fun `executionDevices`(): List<DeviceView>
    
    /**
     * Threads page: pinned, sections, recent.
     */
    fun `frontPage`(): FrontPage
    
    fun `isDemo`(): kotlin.Boolean
    
    /**
     * Direct (SSH) mode.
     */
    fun `isDirect`(): kotlin.Boolean
    
    /**
     * Plan / rate-limit usage of the agent logins on a device. `force`
     * re-probes the providers; otherwise the host's last probe is served.
     */
    suspend fun `listAgentUsage`(`deviceId`: kotlin.String, `force`: kotlin.Boolean): List<AgentUsage>
    
    /**
     * Drives / volumes to browse beyond home (empty on older engines).
     */
    suspend fun `listDrives`(`deviceId`: kotlin.String): List<DriveEntry>
    
    /**
     * Browse folders on a device (`None` = its home folder).
     */
    suspend fun `listFolders`(`deviceId`: kotlin.String, `path`: kotlin.String?): FolderListing
    
    /**
     * Harness catalog of an execution device (static fallback when it's
     * unreachable).
     */
    suspend fun `listHarnesses`(`deviceId`: kotlin.String): List<HarnessInfo>
    
    /**
     * Model catalog for `harness` on `device_id` (normalized; static fallback).
     */
    suspend fun `listModels`(`deviceId`: kotlin.String, `harness`: kotlin.String): List<ModelInfo>
    
    suspend fun `listRefs`(`deviceId`: kotlin.String, `repoPath`: kotlin.String): List<RepoRef>
    
    fun `markSeen`(`chatId`: kotlin.String)
    
    /**
     * Reorder a pin between neighbours (`None` at either end).
     */
    fun `movePin`(`chatId`: kotlin.String, `after`: kotlin.String?, `before`: kotlin.String?)
    
    /**
     * App is backgrounding: persist now; pause time-driven work.
     */
    fun `onBackground`()
    
    /**
     * App returned to the foreground: resume, redial/probe rooms.
     */
    fun `onForeground`()
    
    /**
     * Open (or return the open) session — instant from the local snapshot.
     */
    fun `openSession`(`chatId`: kotlin.String): SessionHandle
    
    fun `orgId`(): kotlin.String
    
    fun `pinSession`(`chatId`: kotlin.String)
    
    /**
     * Warm the most relevant sessions (capped).
     */
    fun `preloadSessions`()
    
    fun `project`(`spaceId`: kotlin.String): ProjectView?
    
    /**
     * Active sessions without a project.
     */
    fun `projectlessSessions`(): List<SessionRow>
    
    fun `projects`(): List<ProjectView>
    
    fun `pullRequests`(): PullRequestGroups
    
