     */
    suspend fun `switchSessionRef`(`chatId`: kotlin.String, `reference`: RepoRef)
    
    fun `unarchiveSession`(`chatId`: kotlin.String)
    
    fun `unpinSession`(`chatId`: kotlin.String)
    
    /**
