/**
 * One transcript's layout engine.
 */
public interface TranscriptViewInterface {
    
    /**
     * Follow a session's transcript: every snapshot (coalesced by the
     * client) becomes a layout input. Returns false for an unknown chat.
     */
    fun `attach`(`client`: CoreClient, `chatId`: kotlin.String): kotlin.Boolean
    
    fun `closeEngine`()
    
    /**
     * The latest published frame.
     */
    fun `frame`(): LayoutFrame
    
    /**
     * Feed markdown fixtures directly (demo screens, benchmarks, tests).
     */
    fun `setDebugEntries`(`entries`: List<DebugEntry>, `working`: kotlin.Boolean)
    
    fun `setViewport`(`width`: kotlin.Float, `textScale`: kotlin.Float)
    
    /**
     * Expand/collapse a disclosure (tool group, long user message).
     */
    fun `toggle`(`key`: kotlin.ULong)
    
    /**
     * Flip one tool row's inline detail (`open` = its state as painted).
     */
    fun `toggleDetail`(`row`: kotlin.ULong, `detail`: kotlin.ULong, `open`: kotlin.Boolean)
    
    companion object
}

