sealed class AuthCallback {
    
    data class Code(
        val `code`: kotlin.String, 
        val `state`: kotlin.String?) : AuthCallback()
        
    {
        

        companion object
    }
    
    data class Error(
        val `error`: kotlin.String, 
        val `description`: kotlin.String?) : AuthCallback()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAuthCallback : FfiConverterRustBuffer<AuthCallback>{
    override fun read(buf: ByteBuffer): AuthCallback {
        return when(buf.getInt()) {
            1 -> AuthCallback.Code(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            2 -> AuthCallback.Error(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AuthCallback): ULong = when(value) {
        is AuthCallback.Code -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterOptionalString.allocationSize(value.`state`)
            )
        }
        is AuthCallback.Error -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`error`)
                + FfiConverterOptionalString.allocationSize(value.`description`)
            )
        }
    }

    override fun write(value: AuthCallback, buf: ByteBuffer) {
        when(value) {
            is AuthCallback.Code -> {
                buf.putInt(1)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterOptionalString.write(value.`state`, buf)
                Unit
            }
            is AuthCallback.Error -> {
                buf.putInt(2)
                FfiConverterString.write(value.`error`, buf)
                FfiConverterOptionalString.write(value.`description`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






