/**
 * Coalesced change notification. Pull the new state after receiving one;
 * delivered on a client thread — hop to the main thread and return fast.
 */
sealed class ClientEvent {
    
    /**
     * `workspace()` advanced.
     */
    data class WorkspaceChanged(
        val `revision`: kotlin.ULong) : ClientEvent()
        
    {
        

        companion object
    }
    
    /**
     * A session's transcript advanced (the layout engine consumes it in Rust;
     * this is informational for the platform).
     */
    data class SessionChanged(
        val `chatId`: kotlin.String, 
        val `revision`: kotlin.ULong) : ClientEvent()
        
    {
        

        companion object
    }
    
    /**
     * A session's `composer()` advanced.
     */
    data class ComposerChanged(
        val `chatId`: kotlin.String, 
        val `revision`: kotlin.ULong) : ClientEvent()
        
    {
        

        companion object
    }
    
    data class ConnectivityChanged(
        val `connectivity`: uniffi.zeron_core.Connectivity) : ClientEvent()
        
    {
        

        companion object
    }
    
    /**
     * The WorkOS pair rotated — persist it now (the old refresh token is spent).
     */
    data class AuthRefreshed(
        val `tokens`: uniffi.zeron_core.AuthTokens) : ClientEvent()
        
    {
        

        companion object
