sealed class CoreException: kotlin.Exception() {
    
    class NotFound(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    
    class InvalidArgument(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    
    /**
     * The host device could not be reached over the relay.
     */
    class HostUnavailable(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    
    class Unsupported(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    
    /**
     * The host answered with an error (bad request, git failure, …).
     */
    class HostException(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    
    class Network(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    
    /**
     * Credentials rejected. Irrecoverable cases also raise `AuthExpired`.
     */
    class Auth(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    
    class Storage(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    
    class NotImplemented(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    
    class Closed(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    class Internal(
        
        val reason: kotlin.String
        ) : CoreException() {
        override val message
            get() = reason
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

