/**
 * How the client authenticates against the edge.
 */
sealed class Credentials {
    
    /**
     * WorkOS session scoped to `org_id`.
     */
    data class WorkOs(
        val `userId`: kotlin.String, 
        val `orgId`: kotlin.String, 
        val `tokens`: uniffi.zeron_core.AuthTokens) : Credentials()
        
    {
        

        companion object
    }
    
    /**
     * `AUTH_MODE=dev` edge: the bearer is `userId@orgId`.
     */
    data class Dev(
        val `userId`: kotlin.String, 
        val `orgId`: kotlin.String) : Credentials()
        
    {
        

        companion object
    }
    
    /**
     * Fully offline dataset with a simulated host.
     */
    data class Demo(
        val `options`: uniffi.zeron_core.DemoOptions) : Credentials()
        
    {
        

        companion object
    }
    
    /**
     * SSH straight to the user's own machine (no edge, no account).
     */
    data class Direct(
        val `target`: uniffi.zeron_core.SshTarget) : Credentials()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCredentials : FfiConverterRustBuffer<Credentials>{
    override fun read(buf: ByteBuffer): Credentials {
        return when(buf.getInt()) {
            1 -> Credentials.WorkOs(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterTypeAuthTokens.read(buf),
                )
            2 -> Credentials.Dev(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> Credentials.Demo(
                FfiConverterTypeDemoOptions.read(buf),
                )
            4 -> Credentials.Direct(
                FfiConverterTypeSshTarget.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Credentials): ULong = when(value) {
        is Credentials.WorkOs -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`userId`)
                + FfiConverterString.allocationSize(value.`orgId`)
                + FfiConverterTypeAuthTokens.allocationSize(value.`tokens`)
            )
        }
        is Credentials.Dev -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`userId`)
                + FfiConverterString.allocationSize(value.`orgId`)
            )
        }
        is Credentials.Demo -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeDemoOptions.allocationSize(value.`options`)
            )
        }
        is Credentials.Direct -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeSshTarget.allocationSize(value.`target`)
            )
        }
    }

    override fun write(value: Credentials, buf: ByteBuffer) {
        when(value) {
            is Credentials.WorkOs -> {
                buf.putInt(1)
                FfiConverterString.write(value.`userId`, buf)
                FfiConverterString.write(value.`orgId`, buf)
                FfiConverterTypeAuthTokens.write(value.`tokens`, buf)
                Unit
            }
            is Credentials.Dev -> {
                buf.putInt(2)
                FfiConverterString.write(value.`userId`, buf)
                FfiConverterString.write(value.`orgId`, buf)
                Unit
            }
            is Credentials.Demo -> {
                buf.putInt(3)
                FfiConverterTypeDemoOptions.write(value.`options`, buf)
                Unit
            }
            is Credentials.Direct -> {
                buf.putInt(4)
                FfiConverterTypeSshTarget.write(value.`target`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





